const body = $json.body || $json;
const entry = (body.entry || [])[0] || {};
const change = ((entry.changes || [])[0] || {}).value || {};
const msg = ((change.messages || [])[0]) || {};
const text = String((msg.text || {}).body || msg.button?.text || body.texto || '').trim();
const from = String(msg.from || body.from || body.whatsapp || '').trim();
const negocio = String(body.negocio || body.slug || change.metadata?.phone_number_id || 'default').trim();
return [{ json: {
  ok: true,
  sistema: '09-wasap-task-faq-citas',
  etapa: 'entrada',
  from,
  text,
  textLower: text.toLowerCase(),
  negocio,
  rawHasMeta: Array.isArray(body.entry),
  status: 'normalizado',
  siguiente: 'intent_router',
  todo: 'TODO: verify token GET + credencial Meta',
  at: new Date().toISOString()
}}];
